	var n, x int
	var s string
	fmt.Scan(&n, &x, &s)
	copy(cc[:], s)

	if x == 0 {
		if n == 1 && cc[0] == '0' {
			fmt.Println(1)
		} else {
			fmt.Println(0)
		}
		return
	}

	ff[0] = 1
	ff[1] = 1
	for i := 2; i <= x; i++ {
		ff[i] = (ff[i-1] + ff[i-2]) % (MD - 1)
