		for l := 0; l < n; l++ {
			for r := l; r < n; r++ {
				var z int64
				for m := l; m <= r; m++ {
					z += int64(ds[i-1][l][m]) * int64(ds[i-2][m][r])
				}
				ds[i][l][r] = int(z % MD)
			}
		}
	}

